css:
.fmd-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.fmd-root,.fmd-root *,.fmd-root *::before,.fmd-root *::after{box-sizing:border-box}
.fmd-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.fmd-root img{display:block;border:0;max-width:none}
.fmd-root > [data-node-id]{will-change:transform}
.fmd-root [hidden]{display:none!important}
.fmd-root [data-sh-theme="dark"]{display:none!important}
.fmd-root[data-theme="dark"] [data-sh-theme="dark"]{display:block!important}
.fmd-root[data-theme="dark"] [data-sh-theme="dark"]{display:none!important}
.fmd-root .fmd_n2142_1870{align-content:stretch;display:flex;gap:11px;align-items:center;padding-top:271px;position:relative;flex-shrink:0}
.fmd-root .fmd_n2205_321{background-color:var(--wa-bg, #fff);align-content:stretch;display:flex;height:35px;align-items:center;justify-content:center;position:relative;flex-shrink:0;width:60px}
.fmd-root .fmd_n2205_321::after{content:"";position:absolute;inset:-0px;border:1px solid var(--wa-line, #303842);border-radius:inherit;pointer-events:none}
.fmd-root .fmd_nI2205_321_2205_210{word-break:break-word;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:520;line-height:17px;font-style:normal;position:relative;flex-shrink:0;color:var(--wa-text-sub, #303842);font-size:14px;text-align:center;white-space:nowrap;width:29px}
.fmd-root .fmd_n2205_300{background-color:var(--wa-bg, #fff);align-content:stretch;display:flex;height:57px;align-items:center;justify-content:center;position:relative;flex-shrink:0;width:109px}
.fmd-root .fmd_n2205_300::after{content:"";position:absolute;inset:-0px;border:1px solid var(--wa-line, #303842);border-radius:inherit;pointer-events:none}
.fmd-root .fmd_nI2205_300_2205_210{word-break:break-word;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:500;line-height:42px;font-style:normal;position:relative;flex-shrink:0;color:var(--wa-text-sub, #303842);font-size:12px;text-align:center;white-space:nowrap;width:57px}
.fmd-root .fmd_x3{line-height:normal;margin-bottom:0}
.fmd-root .fmd_x4{line-height:normal;margin-bottom:0}
.fmd-root .fmd_x5{line-height:normal}
.fmd-root [data-name="Symbol/SPST (Horizontal) Wrap"] > * > [data-name="Glyph"] > [data-name="Glyph"]{transform-origin:0 0;transform:translate(0,15px) rotate(-90deg)}
.fmd-root{position:absolute;inset:0;background:transparent;z-index:auto;overflow:visible}
.fmd-root > [data-node-id="2142:296"]{width:1900px;height:1070px}
.fmd-root[data-theme="dark"]{color:var(--wa-point, #e3e9f2)}
.fmd-root[data-theme="dark"] [data-name="Button/Ack (Hover)"] p{color:var(--wa-text, #0e1a2c)!important}
.fmd-root[data-theme="dark"] [data-name="Frame 8"] > [data-name="logo chip"] img{filter:brightness(0) invert(1)!important}
.fmd-root[data-theme="dark"] [data-name="Frame 8"] > [data-name="WEMB Studio"]{color:var(--wa-text, #fff)!important}
.fmd-root[data-theme="dark"] :is([data-name="Side Panel (Left)"],[data-name="Side Panel (Right)"]) > [data-name="Panel Body"]{box-shadow:inset 0 0 0 1px rgba(255,255,255,.07),0 10px 30px rgba(0,0,0,.45)!important}
.fmd-root[data-theme="dark"] :is([data-name="Widget/Weather"] > [data-name="Row"],[data-name="Widget/Alarm Event"] > [data-name="Button Group"],[data-name="Widget/Mini Map"] > [data-name="Body"],[data-name="Widget/Plant Generation"] > [data-name="Body"],[data-name="Widget/Weekly Solar Generation"] > [data-name="Body"]){background:var(--wa-surface, #1f252e)!important;box-shadow:inset 0 0 0 1px rgba(255,255,255,.07),inset 0 1px 0 rgba(255,255,255,.05),0 6px 16px rgba(0,0,0,.35)!important}
.fmd-root[data-theme="dark"] :is([data-name="Widget/Alarm Event"],[data-name="Widget/Mini Map"]) > [data-name="Header"],.fmd-root[data-theme="dark"] :is([data-name="Widget/Plant Generation"],[data-name="Widget/Weekly Solar Generation"]) > [data-name="Body"] > [data-name="Header"]{background:linear-gradient(to top,var(--wa-point, #3b82ea),var(--wa-point, #1f5fcf))!important;box-shadow:0 4px 12px rgba(31,95,207,.35),inset 0 1px 0 rgba(255,255,255,.18)!important}
.fmd-root[data-theme="dark"] :is([data-name="Button/Solar"],[data-name="Button/Power Equipment"]) > [data-name="Body"] > [data-name="Background"]{background:linear-gradient(to right,color-mix(in srgb, var(--wa-point, rgb(59 130 234)) 55%, transparent) 28%,var(--wa-point, #2466d6) 62%)!important}
.fmd-root[data-theme="dark"] [data-name="Key Background"]{background:linear-gradient(to left,var(--wa-point, #3b82ea),var(--wa-point, #1f5fcf) 53%)!important}
.fmd-root[data-theme="dark"] [data-name^="Item/"] [data-name="Value"]{color:var(--wa-text, #f1f3f8)!important}
.fmd-root[data-theme="dark"] [data-name^="Direction/"] p,.fmd-root[data-theme="dark"] p[data-name^="Direction/"]{color:var(--wa-point, #1d2747)!important}
.fmd-root[data-theme="dark"] [data-name^="Meter Card/"] [data-name="Title"]{color:var(--wa-text, #0f1420)!important;font-weight:600}
.fmd-root[data-theme="dark"] [data-name="Badge/Critical"] p{color:var(--wa-danger, #ff5a57)!important}
.fmd-root[data-theme="dark"] [data-name^="Badge/"]:not([data-name$=" Wrap"]){background:var(--wa-surface, #232a35)!important}
.fmd-root[data-theme="dark"] [data-name^="Badge/"]:not([data-name$=" Wrap"])::after{border-color:color-mix(in srgb, var(--wa-line, rgb(255 255 255)) 12%, transparent)!important}
.fmd-root[data-theme="dark"] .fmd_n2205_321{background-color:var(--wa-surface, #161a21)}
.fmd-root[data-theme="dark"] .fmd_n2205_321::after{border-color:var(--wa-line, #80858e)}
.fmd-root[data-theme="dark"] .fmd_nI2205_321_2205_210{color:var(--wa-text-sub, #cfd1d4)}
.fmd-root[data-theme="dark"] .fmd_n2205_300{background-color:var(--wa-surface, #161a21)}
